let file = """{"version":3,"file":"useFeatureFlags-BSa5Y3eR.js","names":[],"sources":["../../src/config/billingWeb.ts","../../src/platform/remoteConfig/serverFeatureFlag.ts","../../src/composables/useFeatureFlags.ts"],"sourcesContent":["import type { HostedBillingDestination } from '@comfyorg/account-core/billing'\n\nimport { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\n\nconst LOCAL_HOSTNAMES = new Set(['localhost', '127.0.0.1', '[::1]'])\n\n/** The SDK owns the vocabulary; the server resolves it per user through the `hosted_billing_destination` flag. */\nexport type { HostedBillingDestination }\n\n/**\n * The single narrowing boundary for the raw wire value. Anything but the\n * exact `billing_web` variant (absent, a typo, a boolean coerced by an\n * override) stays on the provider page, so a bad read can never send a\n * customer to an origin that is not serving yet.\n */\nexport function normalizeHostedBillingDestination(\n  value: unknown\n): HostedBillingDestination {\n  return value === 'billing_web' ? 'billing_web' : 'stripe'\n}\n\nfunction validateBillingWebUrl(value: string): URL | null {\n  try {\n    const url = new URL(value)\n    if (url.username || url.password) return null\n    if (url.protocol === 'https:') return url\n\n    if (\n      import.meta.env.DEV &&\n      url.protocol === 'http:' &&\n      LOCAL_HOSTNAMES.has(url.hostname)\n    ) {\n      return url\n    }\n  } catch {\n    return null\n  }\n\n  return null\n}\n\n/**\n * The server-provided origin (`/api/features`' `billing_web_url`, one per\n * environment) takes precedence; `VITE_BILLING_WEB_URL` only fills in when\n * the server sends nothing, which is how local dev points itself at a\n * `pnpm dev:cloud:billing-web` instance.\n *\n * A server value that fails validation does *not* fall through to the env\n * var: the env fallback exists for local dev against a backend that has no\n * billing-web origin configured at all, not for a real deployment that sent\n * a broken one. Silently substituting a build-time default for a live\n * backend's malformed answer would route a real customer to whatever origin\n * happens to be baked into that build. Failing closed to the provider page\n * is the safer read, and it matches the fail-closed posture the rest of the\n * hosted-billing rollout already takes for an unresolved destination.\n */\nexport function getBillingWebUrl(): URL | null {\n  const fromServer = remoteConfig.value.billing_web_url\n  if (typeof fromServer === 'string' && fromServer !== '') {\n    return validateBillingWebUrl(fromServer)\n  }\n\n  const fromEnv = import.meta.env.VITE_BILLING_WEB_URL\n  return fromEnv ? validateBillingWebUrl(fromEnv) : null\n}\n","/**\n * Known server feature flags (top-level, not extensions)\n */\nexport enum ServerFeatureFlag {\n  SUPPORTS_PREVIEW_METADATA = 'supports_preview_metadata',\n  MAX_UPLOAD_SIZE = 'max_upload_size',\n  MANAGER_SUPPORTS_V4 = 'extension.manager.supports_v4',\n  MODEL_UPLOAD_BUTTON_ENABLED = 'model_upload_button_enabled',\n  ASSET_DELETION_ENABLED = 'asset_deletion_enabled',\n  PRIVATE_MODELS_ENABLED = 'private_models_enabled',\n  ONBOARDING_SURVEY_ENABLED = 'onboarding_survey_enabled',\n  LINEAR_TOGGLE_ENABLED = 'linear_toggle_enabled',\n  PARTNER_NODE_GOVERNANCE_ENABLED = 'partner_node_governance_enabled',\n  PARTNER_RUN_GATE_ENABLED = 'partner_run_gate_enabled',\n  PARTNER_NODE_TOKEN = 'partner_node_token',\n  USER_SECRETS_ENABLED = 'user_secrets_enabled',\n  NODE_REPLACEMENTS = 'node_replacements',\n  NODE_LIBRARY_ESSENTIALS_ENABLED = 'node_library_essentials_enabled',\n  COMFYHUB_UPLOAD_ENABLED = 'comfyhub_upload_enabled',\n  COMFYHUB_PROFILE_GATE_ENABLED = 'comfyhub_profile_gate_enabled',\n  HOSTED_BILLING_DESTINATION = 'hosted_billing_destination',\n  SHOW_SIGNIN_BUTTON = 'show_signin_button',\n  UNIFIED_CLOUD_AUTH = 'unified_cloud_auth',\n  UNIFIED_WEB_SESSION = 'unified_web_session',\n  SSO_ENABLED = 'sso_enabled',\n  LOCAL_WEB_SSO = 'local_web_sso',\n  BILLING_CONTROL_ENABLED = 'billing_control_enabled',\n  MEMBER_CREDIT_LIMITS_ENABLED = 'member_credit_limits_enabled',\n  LEGACY_BILLING_MIGRATION_ENABLED = 'legacy_billing_migration_enabled',\n  EMBEDDED_CHECKOUT_ENABLED = 'embedded_checked_enabled',\n  BILLING_SDK_TOPUP_ENABLED = 'billing_sdk_topup_enabled',\n  BILLING_SDK_SUBSCRIPTION_ENABLED = 'billing_sdk_subscription_enabled',\n  V1_PAYMENT_RECOVERY = 'v1_payment_recovery',\n  FREE_TIER_JOB_ALLOWANCE_ENABLED = 'free_tier_job_allowance_enabled',\n  SIGNUP_TURNSTILE = 'signup_turnstile',\n  SUPPORTS_MODEL_TYPE_TAGS = 'supports_model_type_tags',\n  ONBOARDING_TOUR_ENABLED = 'onboarding_tour_enabled',\n  AGENT_IN_APP_EXPERIENCE = 'agent-in-app-experience'\n}\n","import { computed, reactive, readonly, watchEffect } from 'vue'\nimport type { Ref } from 'vue'\n\nimport { normalizeHostedBillingDestination } from '@/config/billingWeb'\nimport { isCloud, isNightly } from '@/platform/distribution/types'\nimport {\n  cachedBillingControlEnabled,\n  cachedLegacyBillingMigrationEnabled,\n  cachedV1PaymentRecovery,\n  isAuthenticatedConfigLoaded,\n  remoteConfig,\n  sessionAgentGrant,\n  sessionAgentGrantValidUntil\n} from '@/platform/remoteConfig/remoteConfig'\nimport { ServerFeatureFlag } from '@/platform/remoteConfig/serverFeatureFlag'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { api } from '@/scripts/api'\nimport { getDevOverride } from '@/utils/devFeatureFlagOverride'\nimport { getSessionOverride } from '@/utils/sessionFeatureFlagOverride'\n\nfunction reportFeatureFlagEvaluation<T>(flagKey: string, value: T): T {\n  useTelemetry()?.trackFeatureFlagEvaluation(flagKey, value)\n  return value\n}\n\n/**\n * Resolves a feature flag value with session override > dev override >\n * remoteConfig > serverFeature priority.\n */\nfunction resolveFlag<T>(\n  flagKey: string,\n  remoteConfigValue: T | undefined,\n  defaultValue: T\n): T {\n  const sessionOverride = getSessionOverride<T>(flagKey)\n  if (sessionOverride !== undefined) return sessionOverride\n\n  const override = getDevOverride<T>(flagKey)\n  if (override !== undefined) return override\n  return remoteConfigValue ?? api.getServerFeature(flagKey, defaultValue)\n}\n\n/**\n * A flag that enables a payment flow: same channels as `resolveFlag`, but only\n * a literal `true` counts. A malformed wire value (`'true'`, `1`) or a failed\n * lookup resolves to false rather than switching a charge onto a new transport.\n *\n * Needs no auth gate: the server returns a concrete `false` for these keys to\n * an unauthenticated caller, so the anonymous window resolves to the legacy\n * rail and cannot enable a flow before authenticated config confirms it.\n */\nfunction resolveStrictBooleanFlag(\n  flagKey: string,\n  remoteConfigValue: boolean | undefined\n): boolean {\n  try {\n    return resolveFlag<unknown>(flagKey, remoteConfigValue, false) === true\n  } catch {\n    return false\n  }\n}\n\n/**\n * Resolves a per-user, Cloud-only flag that selects backend behavior. Off the\n * Cloud build it is always false; during the auth window it falls back to the\n * cached session value so anonymous bootstrap config cannot route the user to\n * the wrong backend before authenticated config confirms the flag.\n */\nfunction resolveAuthGatedFlag(\n  flagKey: string,\n  remoteConfigValue: boolean | undefined,\n  cachedValue: Ref<boolean | undefined>\n): boolean {\n  const sessionOverride = getSessionOverride<boolean>(flagKey)\n  if (sessionOverride !== undefined) return sessionOverride\n\n  const override = getDevOverride<boolean>(flagKey)\n  if (override !== undefined) return override\n\n  if (!isCloud) return false\n  if (!isAuthenticatedConfigLoaded.value) return cachedValue.value ?? false\n\n  return remoteConfigValue ?? api.getServerFeature(flagKey, false)\n}\n\n/**\n * Resolves a per-user allowlist flag. Before the first authenticated answer it\n * is off; after one, a failed refresh falls back to that answer so a blip\n * cannot pull a granted surface out from under the user mid-session. Unlike\n * `resolveAuthGatedFlag` the fallback is never read from storage — a persisted\n * grant is what let one browser show the surface while another hid it for the\n * same account (PM-1707).\n */\nfunction resolveWhitelistFlag(\n  flagKey: string,\n  remoteConfigValue: boolean | undefined,\n  grantedThisSession: Ref<boolean | undefined>,\n  grantValidUntil: Ref<number | undefined>\n): boolean {\n  const sessionOverride = getSessionOverride<boolean>(flagKey)\n  if (sessionOverride !== undefined) return sessionOverride\n\n  const override = getDevOverride<boolean>(flagKey)\n  if (override !== undefined) return override\n\n  if (!isCloud) return false\n  if (!isAuthenticatedConfigLoaded.value)\n    return (\n      grantedThisSession.value === true &&\n      (grantValidUntil.value ?? 0) > Date.now()\n    )\n\n  return remoteConfigValue === true\n}\n\n/**\n * Composable for reactive access to server-side feature flags\n */\nexport function useFeatureFlags() {\n  const hostedBillingDestination = () =>\n    normalizeHostedBillingDestination(\n      resolveFlag(\n        ServerFeatureFlag.HOSTED_BILLING_DESTINATION,\n        remoteConfig.value.hosted_billing_destination,\n        'stripe'\n      )\n    )\n\n  const flags = reactive({\n    get supportsPreviewMetadata() {\n      return api.getServerFeature(ServerFeatureFlag.SUPPORTS_PREVIEW_METADATA)\n    },\n    get maxUploadSize() {\n      return api.getServerFeature(ServerFeatureFlag.MAX_UPLOAD_SIZE)\n    },\n    get supportsManagerV4() {\n      return api.getServerFeature(ServerFeatureFlag.MANAGER_SUPPORTS_V4)\n    },\n    get modelUploadButtonEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.MODEL_UPLOAD_BUTTON_ENABLED,\n        remoteConfig.value.model_upload_button_enabled,\n        false\n      )\n    },\n    get assetDeletionEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.ASSET_DELETION_ENABLED,\n        undefined,\n        false\n      )\n    },\n    get privateModelsEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.PRIVATE_MODELS_ENABLED,\n        remoteConfig.value.private_models_enabled,\n        false\n      )\n    },\n    get onboardingSurveyEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.ONBOARDING_SURVEY_ENABLED,\n        remoteConfig.value.onboarding_survey_enabled,\n        false\n      )\n    },\n    get linearToggleEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.LINEAR_TOGGLE_ENABLED,\n        remoteConfig.value.linear_toggle_enabled,\n        isNightly\n      )\n    },\n    get partnerNodeGovernanceEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.PARTNER_NODE_GOVERNANCE_ENABLED,\n        remoteConfig.value.partner_node_governance_enabled,\n        false\n      )\n    },\n    get partnerRunGateEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.PARTNER_RUN_GATE_ENABLED,\n        remoteConfig.value.partner_run_gate_enabled,\n        true\n      )\n    },\n    get partnerNodeTokenEnabled() {\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.PARTNER_NODE_TOKEN,\n        remoteConfig.value.partner_node_token\n      )\n    },\n    get userSecretsEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.USER_SECRETS_ENABLED,\n        remoteConfig.value.user_secrets_enabled,\n        false\n      )\n    },\n    get nodeReplacementsEnabled() {\n      return api.getServerFeature(ServerFeatureFlag.NODE_REPLACEMENTS, false)\n    },\n    get nodeLibraryEssentialsEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.NODE_LIBRARY_ESSENTIALS_ENABLED,\n        remoteConfig.value.node_library_essentials_enabled,\n        isNightly || import.meta.env.DEV\n      )\n    },\n    get comfyHubUploadEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.COMFYHUB_UPLOAD_ENABLED,\n        remoteConfig.value.comfyhub_upload_enabled,\n        false\n      )\n    },\n    get comfyHubProfileGateEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.COMFYHUB_PROFILE_GATE_ENABLED,\n        remoteConfig.value.comfyhub_profile_gate_enabled,\n        false\n      )\n    },\n    get hostedBillingDestination() {\n      return hostedBillingDestination()\n    },\n    get hostedBillingWebEnabled() {\n      return hostedBillingDestination() === 'billing_web'\n    },\n    get showSignInButton(): boolean | undefined {\n      return api.getServerFeature<boolean | undefined>(\n        ServerFeatureFlag.SHOW_SIGNIN_BUTTON,\n        undefined\n      )\n    },\n    get unifiedCloudAuthEnabled() {\n      if (!isCloud) return false\n\n      return resolveFlag(\n        ServerFeatureFlag.UNIFIED_CLOUD_AUTH,\n        remoteConfig.value.unified_cloud_auth,\n        false\n      )\n    },\n    get unifiedWebSessionEnabled() {\n      if (!isCloud) return false\n\n      const key = ServerFeatureFlag.UNIFIED_WEB_SESSION\n      // Overrides skip the server's web_session_enabled pairing; whoever overrides\n      // this key must also be in the web_session_enabled set.\n      const value =\n        getSessionOverride<unknown>(key) ??\n        getDevOverride<unknown>(key) ??\n        remoteConfig.value.unified_web_session\n      return value === true\n    },\n    get ssoEnabled() {\n      if (!isCloud) return false\n\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.SSO_ENABLED,\n        remoteConfig.value.sso_enabled\n      )\n    },\n    /** Browser sign-in for a local ComfyUI that Desktop does not host. */\n    get localWebSsoEnabled() {\n      if (isCloud) return false\n\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.LOCAL_WEB_SSO,\n        remoteConfig.value.local_web_sso\n      )\n    },\n    get billingControlEnabled() {\n      return resolveAuthGatedFlag(\n        ServerFeatureFlag.BILLING_CONTROL_ENABLED,\n        remoteConfig.value.billing_control_enabled,\n        cachedBillingControlEnabled\n      )\n    },\n    get memberCreditLimitsEnabled() {\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.MEMBER_CREDIT_LIMITS_ENABLED,\n        remoteConfig.value.member_credit_limits_enabled\n      )\n    },\n    get legacyBillingMigrationEnabled() {\n      return resolveAuthGatedFlag(\n        ServerFeatureFlag.LEGACY_BILLING_MIGRATION_ENABLED,\n        remoteConfig.value.legacy_billing_migration_enabled,\n        cachedLegacyBillingMigrationEnabled\n      )\n    },\n    get embeddedCheckoutEnabled() {\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.EMBEDDED_CHECKOUT_ENABLED,\n        remoteConfig.value.embedded_checked_enabled\n      )\n    },\n    get billingSdkTopupEnabled() {\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.BILLING_SDK_TOPUP_ENABLED,\n        remoteConfig.value.billing_sdk_topup_enabled\n      )\n    },\n    /** The SDK rail runs on the unified session, so it needs both flags. */\n    get billingSdkTopupRailEnabled() {\n      return this.billingSdkTopupEnabled && this.unifiedCloudAuthEnabled\n    },\n    get billingSdkSubscriptionEnabled() {\n      return resolveStrictBooleanFlag(\n        ServerFeatureFlag.BILLING_SDK_SUBSCRIPTION_ENABLED,\n        remoteConfig.value.billing_sdk_subscription_enabled\n      )\n    },\n    get billingSdkSubscriptionRailEnabled() {\n      return this.billingSdkSubscriptionEnabled && this.unifiedCloudAuthEnabled\n    },\n    get v1PaymentRecovery() {\n      return resolveAuthGatedFlag(\n        ServerFeatureFlag.V1_PAYMENT_RECOVERY,\n        remoteConfig.value.v1_payment_recovery,\n        cachedV1PaymentRecovery\n      )\n    },\n    get freeTierJobAllowanceEnabled() {\n      const config = remoteConfig.value as typeof remoteConfig.value & {\n        free_tier_job_allowance_enabled?: boolean\n      }\n      return resolveFlag(\n        ServerFeatureFlag.FREE_TIER_JOB_ALLOWANCE_ENABLED,\n        config.free_tier_job_allowance_enabled,\n        false\n      )\n    },\n    get signupTurnstileMode() {\n      return resolveFlag(\n        ServerFeatureFlag.SIGNUP_TURNSTILE,\n        remoteConfig.value.signup_turnstile,\n        'off'\n      )\n    },\n    get supportsModelTypeTags() {\n      return resolveFlag(\n        ServerFeatureFlag.SUPPORTS_MODEL_TYPE_TAGS,\n        remoteConfig.value.supports_model_type_tags,\n        false\n      )\n    },\n    get onboardingTourEnabled() {\n      return resolveFlag(\n        ServerFeatureFlag.ONBOARDING_TOUR_ENABLED,\n        remoteConfig.value.onboarding_tour_enabled,\n        false\n      )\n    },\n    get assetsEnabled() {\n      return isCloud || resolveFlag('assets', undefined, false)\n    },\n    get agentInAppExperienceEnabled() {\n      return resolveWhitelistFlag(\n        ServerFeatureFlag.AGENT_IN_APP_EXPERIENCE,\n        remoteConfig.value['agent-in-app-experience'],\n        sessionAgentGrant,\n        sessionAgentGrantValidUntil\n      )\n    }\n  })\n\n  const featureFlag = <T = unknown>(featurePath: string, defaultValue?: T) =>\n    computed(() => api.getServerFeature(featurePath, defaultValue))\n\n  return {\n    flags: readonly(flags),\n    featureFlag\n  }\n}\n\nexport function startFeatureFlagTelemetry() {\n  const { flags } = useFeatureFlags()\n\n  return watchEffect(() => {\n    const evaluations = {\n      [ServerFeatureFlag.SUPPORTS_PREVIEW_METADATA]:\n        flags.supportsPreviewMetadata,\n      [ServerFeatureFlag.MAX_UPLOAD_SIZE]: flags.maxUploadSize,\n      [ServerFeatureFlag.MANAGER_SUPPORTS_V4]: flags.supportsManagerV4,\n      [ServerFeatureFlag.MODEL_UPLOAD_BUTTON_ENABLED]:\n        flags.modelUploadButtonEnabled,\n      [ServerFeatureFlag.ASSET_DELETION_ENABLED]: flags.assetDeletionEnabled,\n      [ServerFeatureFlag.PRIVATE_MODELS_ENABLED]: flags.privateModelsEnabled,\n      [ServerFeatureFlag.ONBOARDING_SURVEY_ENABLED]:\n        flags.onboardingSurveyEnabled,\n      [ServerFeatureFlag.LINEAR_TOGGLE_ENABLED]: flags.linearToggleEnabled,\n      [ServerFeatureFlag.PARTN